pub fn adaptive_sort<T: Ord + Clone>(a: &mut [T]) {
    let n = a.len();
    if n > 1 {
        introsort(a, 0, n - 1, 2 * (n as f64).log2() as usize);
    }
}

fn introsort<T: Ord + Clone>(a: &mut [T], lo: usize, hi: usize, d: usize) {
    if hi - lo < 16 {
        insertion(a, lo, hi);
    } else if d == 0 {
        heapsort(a, lo, hi);
    } else {
        let p = part(a, lo, hi);
        if p > lo { introsort(a, lo, p - 1, d - 1); }
        if p < hi { introsort(a, p + 1, hi, d - 1); }
    }
}

fn insertion<T: Ord>(a: &mut [T], lo: usize, hi: usize) {
    for i in (lo + 1)..=hi {
        let mut j = i;
        while j > lo && a[j - 1] > a[j] { a.swap(j, j - 1); j -= 1; }
    }
}

fn part<T: Ord + Clone>(a: &mut [T], lo: usize, hi: usize) -> usize {
    let m = lo + (hi - lo) / 2;
    if a[lo] > a[m] { a.swap(lo, m); }
    if a[lo] > a[hi] { a.swap(lo, hi); }
    if a[m] > a[hi] { a.swap(m, hi); }
    a.swap(m, hi);
    let p = a[hi].clone();
    let mut i = lo;
    for j in lo..hi {
        if a[j] <= p { a.swap(i, j); i += 1; }
    }
    a.swap(i, hi);
    i
}

fn heapsort<T: Ord>(a: &mut [T], lo: usize, hi: usize) {
    let n = hi - lo + 1;
    for i in (0..n / 2).rev() { sift(a, lo, i, n); }
    for i in (1..n).rev() {
        a.swap(lo, lo + i);
        sift(a, lo, 0, i);
    }
}

fn sift<T: Ord>(a: &mut [T], lo: usize, s: usize, n: usize) {
    let mut i = s;
    loop {
        let l = 2 * i + 1;
        if l >= n { break; }
        let r = l + 1;
        let m = if r < n && a[lo + r] > a[lo + l] { r } else { l };
        if a[lo + i] >= a[lo + m] { break; }
        a.swap(lo + i, lo + m);
        i = m;
    }
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_sort() {
        let mut arr = vec![3, 1, 4, 1, 5, 9, 2, 6];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![1, 1, 2, 3, 4, 5, 6, 9]);
    }

    #[test]
    fn test_empty_array() {
        let mut arr: Vec<i32> = vec![];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![]);
    }

    #[test]
    fn test_single_element() {
        let mut arr = vec![42];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![42]);
    }
}
